import itertools   # Importing combinations function from Python Itertool module for efficient combination calculation in lists (itertools)
import numpy      # For product operation which is needed to find largest products among two numbers at a time and also sort them based on their multiplication value 'n times' 
from operator import itemgetter    # To use the sorted function with multiple criteria. This will be used for descending order of combination values (product).  

def large_product(list1: List[int], list2:List [int] , n : int) -> Dict[str, float]: 
      if len(list1)!=len(list2):    # Checking both lists have same length. If not then raise an error message and return None (or appropriate value).  
          print("Both input arrays should be of the same size.")    
          return {}      

      elif n>min([len(list1), len(list2)]):  # Checking if 'n' is greater than smallest list length. If yes then raise an error message and return None (or appropriate value).  
            print("Value of N cannot be more than the size of either array.")    
            return {}   

      else:      
          combined = zip(list1, list2)  # Combine both lists into one tuple. Tuples are used for efficient product calculation in numpy library (numpy).  

          combinations_obj=itertools.combinations(combined , n )    # Get all possible pairs of 'n' elements from the combined list, using itertool module function combination().  Iterable object is passed as parameter to this method and it returns an iterator yielding tuples for each element in combinations_obj (itertools).

          product=[np.prod(x) for x in combinations_obj]    # Get all products of 'n' elements from the combined list, using numpy library function prod().  List comprehension is used to get a new iterable object which contains only these calculated values (list), and then pass it into sorted() method with multiple criteria.

          return sorted(product , key=itemgetter(-1) , reverse = True )   # Sort the list of products based on their multiplication value 'n times' in descending order, using operator module function itemgeter().  This will be used for sorting all combinations (tuple pairs from both lists `list1` and `list2`).
